      result[word] = undefined;
      for (let i = 0; i < this.grid.length; i++) {
        for (let j = 0; j < this.grid[i].length; j++) {
          for (const [dx, dy] of directions) {
            if (this.#matches(word, i, j, dx, dy)) { ... }
          }
        }
